//! Actions-only real account/native IO readonly observation and original joins.
use super::*;
fn report(read: i64, accepted: bool) -> Vec<u8> {
    let mut w=Writer::new();w.boolean(accepted).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();let read=read.to_string();w.properties(&[RpcProperty{key:n::im_status::LATEST,value:b"9"},RpcProperty{key:n::im_status::LAST_READ,value:read.as_bytes()},RpcProperty{key:n::im_status::LAST_RECEIVED,value:b"8"}]).unwrap();w.i64(4294967297).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()
}
async fn query_report(peer: &mut CommonPeer, accepted: bool) -> i32 {
    let p=query(peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.u32().unwrap(),1);assert_eq!(a.bytes().unwrap(),b"1_2");peer.send(&[reply(r.call_id,&report(9,accepted))]).await;r.call_id
}
async fn sample_known(accepted: bool) {
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,listener.local_addr().unwrap().port()),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(done,wait)=tokio::sync::oneshot::channel();let db=temp.database.clone();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;ready.send(()).unwrap();target(&mut peer,9,true).await;let id=mark(&mut peer).await;peer.send(&[response(id,false,0)]).await;query_report(&mut peer,accepted).await;assert_eq!(rows(&db),[(2,Some(id),7)]);wait.await.unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap()[0].id;let decision=bounded(manager.mark_im_user_read(&line,account.revision,message,&"a".repeat(32),true)).await.unwrap();assert_eq!(decision.state,"rejected");
    let view=bounded(manager.reconcile_im_user_read(&line,account.revision,decision.id,true)).await.unwrap();assert_eq!(view.local_state,"rejected");assert_eq!(view.report,if accepted{"reported"}else{"rejected"});assert_eq!(view.reported_last_read,accepted.then(||"9".to_owned()));assert_eq!(manager.im_user_read_history(&line,16).unwrap()[0].state,"rejected");assert_eq!(manager.get(&line,100).await.unwrap().phase,"hosted");assert!(manager.get(&line,100).await.unwrap().im_reconciliation_supported.unwrap());done.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}
#[tokio::test]
async fn im_reconciliation_real_original_account_query_never_converts_a_known_rejection_to_write_ack(){Box::pin(sample_known(true)).await;}
#[tokio::test]
async fn im_reconciliation_real_negative_group_query_is_not_original_user_write_failure_or_sdk_disconnect(){Box::pin(sample_known(false)).await;}
#[tokio::test]
async fn im_reconciliation_no_consent_old_revision_and_unknown_record_do_not_send_native_queries(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,listener.local_addr().unwrap().port()),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(done,wait)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;ready.send(()).unwrap();wait.await.unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();assert_eq!(manager.reconcile_im_user_read(&line,account.revision,1,false).await.err(),Some("app_account_im_reconciliation_consent_required"));assert_eq!(manager.reconcile_im_user_read(&line,2,1,true).await.err(),Some("app_account_revision_conflict"));assert_eq!(bounded(manager.reconcile_im_user_read(&line,account.revision,1,true)).await.err(),Some("app_account_im_reconciliation_not_found"));assert!(rows(&temp.database).is_empty());done.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_reconciliation_current_restart_can_only_observe_unknown_and_cannot_enable_another_nonce(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(second,seen_again)=tokio::sync::oneshot::channel();let(done,wait)=tokio::sync::oneshot::channel();let db=temp.database.clone();
    let serving=tokio::spawn(async move{bounded(async move{let original=listener.into_std().unwrap();let first=TcpListener::from_std(original.try_clone().unwrap()).unwrap();let next=TcpListener::from_std(original).unwrap();let mut peer=CommonPeer::open(first,server.clone()).await;login_message(&mut peer).await;ready.send(()).unwrap();target(&mut peer,9,true).await;let id=mark(&mut peer).await;assert_eq!(rows(&db),[(0,Some(id),7)]);while let Some(p)=peer.next().await{poll(&mut peer,&p).await;}
        let mut peer=CommonPeer::open(next,server).await;login_message(&mut peer).await;second.send(()).unwrap();query_report(&mut peer,true).await;wait.await.unwrap();assert_eq!(rows(&db),[(0,Some(id),7)]);finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap()[0].id;assert!(bounded(manager.mark_im_user_read(&line,account.revision,message,&"a".repeat(32),true)).await.is_err());bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::time::sleep(Duration::from_millis(5)).await;}}).await;assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen_again).await.unwrap();let receipt=manager.im_user_read_history(&line,16).unwrap()[0].id;let observed=bounded(manager.reconcile_im_user_read(&line,account.revision,receipt,true)).await.unwrap();assert_eq!(observed.reported_last_read.as_deref(),Some("9"));assert_eq!(observed.local_state,"uncertain");assert_eq!(manager.im_user_read_history(&line,16).unwrap()[0].state,"uncertain");assert_eq!(bounded(manager.mark_im_user_read(&line,account.revision,message,&"b".repeat(32),true)).await.err(),Some("app_account_im_user_read_uncertain"));done.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
